function localizePakistanDemoReports(items){return items.map(report=>{const place=pakistanDemoPlaces[report.id];return place?{...report,title:place[0],location:place[1],area:place[2],lat:place[3],lng:place[4],description:place[5]||report.description,department:departments[report.category]}:report})}
function loadReports(){try{const saved=localStorage.getItem(STORAGE_KEY);return localizePakistanDemoReports(saved?JSON.parse(saved):initialReports)}catch{return localizePakistanDemoReports(initialReports)}}
function loadRules(){try{return JSON.parse(localStorage.getItem(RULES_KEY))||{baseHigh:72,baseMedium:48,ageBoost:1.4,duplicateBoost:12,urgentBoost:18}}catch{return {baseHigh:72,baseMedium:48,ageBoost:1.4,duplicateBoost:12,urgentBoost:18}}}
let reports = CivicPulseCloud.configured ? [] : loadReports();
async function saveReports(){if(!CivicPulseCloud.configured){localStorage.setItem(STORAGE_KEY,JSON.stringify(reports));return}try{for(const report of reports){if(syncedReports.get(report.id)===JSON.stringify(report))continue;if(typeof report.image==='string'&&report.image.startsWith('data:')){const file=await dataUrlToFile(report.image,`${report.id}-report`);report.image=await CivicPulseCloud.uploadPhoto(file,report.id,'reports')}if(typeof report.resolutionImage==='string'&&report.resolutionImage.startsWith('data:')){const file=await dataUrlToFile(report.resolutionImage,`${report.id}-resolution`);report.resolutionImage=await CivicPulseCloud.uploadPhoto(file,report.id,'resolutions')}await CivicPulseCloud.saveReport(report);syncedReports.set(report.id,JSON.stringify(report))}}catch(error){toast('Could not save to the shared service: '+escapeHtml(error.message))}}
async function dataUrlToFile(dataUrl,filename){const response=await fetch(dataUrl);const blob=await response.blob();const extension=blob.type.split('/')[1]||'jpg';return new File([blob],`${filename}.${extension}`,{type:blob.type||'image/jpeg'})}
async function persistReport(report){if(CivicPulseCloud.configured){await CivicPulseCloud.saveReport(report);return}saveReports()}
function saveRules(){if(CivicPulseCloud.configured){CivicPulseCloud.writeRules(rules).catch(error=>toast('Could not save priority rules: '+escapeHtml(error.message)));return}localStorage.setItem(RULES_KEY,JSON.stringify(rules))}
function escapeHtml(value=''){return String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]))}
function categoryFor(text){const normalized=text.toLowerCase();let best='Other',matches=0;for(const [category,terms] of Object.entries(categoryTerms)){const count=terms.filter(term=>normalized.includes(term)).length;if(count>matches){best=category;matches=count}}return {category:best,confidence:best==='Other'?48:Math.min(98,70+matches*8)}}
function tokenize(text){return new Set(text.toLowerCase().replace(/[^a-z0-9\s]/g,' ').split(/\s+/).filter(word=>word.length>2&&!['the','and','with','near','this','that','has','have','from','onto','there','very'].includes(word)))}
function textSimilarity(left,right){const a=tokenize(left),b=tokenize(right);if(!a.size||!b.size)return 0;let common=0;for(const word of a)if(b.has(word))common++;return common/(a.size+b.size-common)}
function isNear(left,right){if(left.area.toLowerCase()!==right.area.toLowerCase())return false;if(Number.isFinite(left.lat)&&Number.isFinite(right.lat))return Math.hypot((left.lat-right.lat)*111,(left.lng-right.lng)*85)<0.8;return left.location.toLowerCase()===right.location.toLowerCase()}
function findDuplicate(candidate){return reports.filter(report=>report.id!==candidate.id&&report.status!=='Resolved'&&report.category===candidate.category).map(report=>({report,similarity:textSimilarity(candidate.title+' '+candidate.description,report.title+' '+report.description)})).filter(match=>match.similarity>=0.22&&isNear(candidate,match.report)).sort((a,b)=>b.similarity-a.similarity)[0]?.report||null}
function priorityScore(report,duplicate){const ageHours=(Date.now()-report.reportedAt)/3600000;const severe=/danger|injur|school|crossing|flood|leak|dark|emergency|unsafe/i.test(report.title+' '+report.description);return Math.min(100,Math.round((report.priority==='High'?rules.baseHigh:report.priority==='Medium'?rules.baseMedium:30)+Math.min(ageHours,48)*rules.ageBoost+(duplicate?rules.duplicateBoost:0)+(severe?rules.urgentBoost:0)))}
function priorityFromScore(score){return score>=rules.baseHigh?'High':score>=rules.baseMedium?'Medium':'Low'}
function formatAge(timestamp){const hours=Math.max(0,Math.floor((Date.now()-timestamp)/3600000));if(hours<1)return 'Just now';if(hours<24)return `${hours}h ago`;const days=Math.floor(hours/24);return `${days}d ago`}
function formatDate(date){return new Intl.DateTimeFormat('en-PK',{weekday:'short',month:'short',day:'numeric',timeZone:'Asia/Karachi'}).format(date)}
function priorityClass(priority){return `priority-${priority.toLowerCase()}`}
function statusClass(status){return status==='In progress'?'status-progress':status==='Resolved'?'status-resolved':'status-submitted'}
function escapeCategory(category){return escapeHtml(category.replace(' & ',' / '))}
function getVisibleReports(){return [...reports].sort((a,b)=>{const order={High:0,Medium:1,Low:2};return order[a.priority]-order[b.priority]||b.reportedAt-a.reportedAt}).filter(report=>{const matchesPriority=activePriority==='all'||(activePriority==='High'?report.priority==='High':Boolean(report.duplicateOf));const haystack=[report.id,report.title,report.location,report.area,report.category,report.status,report.department,report.description].join(' ').toLowerCase();return matchesPriority&&(statusFilter==='all'||report.status===statusFilter)&&haystack.includes(searchQuery)})}
function render(){renderMetrics();renderRows();renderNeighborhoods();renderActivity();updateNavigation()}
function renderMetrics(){const open=reports.filter(report=>report.status!=='Resolved').length;const urgent=reports.filter(report=>report.status!=='Resolved'&&(report.priority==='High'||(Date.now()-report.reportedAt)>86400000)).length;const resolved=reports.filter(report=>report.status==='Resolved'&&Date.now()-(report.resolvedAt||0)<7*86400000).length;const durations=reports.filter(report=>report.status==='Resolved'&&report.resolvedAt>report.reportedAt).map(report=>(report.resolvedAt-report.reportedAt)/86400000);const average=document.getElementById('metric-average');document.getElementById('metric-open').textContent=open;document.getElementById('metric-urgent').textContent=urgent;document.getElementById('metric-resolved').textContent=resolved;document.getElementById('nav-count').textContent=open;document.getElementById('tab-all').textContent=reports.length;document.getElementById('tab-high').textContent=reports.filter(report=>report.priority==='High').length;document.getElementById('tab-duplicate').textContent=reports.filter(report=>report.duplicateOf).length;document.getElementById('metric-open-note').textContent=`${new Set(reports.map(report=>report.area)).size} local areas`;average.innerHTML=durations.length?`${(durations.reduce((sum,value)=>sum+value,0)/durations.length).toFixed(1)} <small>days</small>`:'— <small>days</small>'}
function renderRows(){const visible=getVisibleReports(),shown=visible.slice(0,visibleLimit);document.getElementById('queue-count').textContent=visible.length;document.getElementById('queue-title').innerHTML=activeView==='departments'?'Department queue <span class="count-badge" id="queue-count">'+visible.length+'</span>':'Reports to triage <span class="count-badge" id="queue-count">'+visible.length+'</span>';document.getElementById('report-rows').innerHTML=shown.map(report=>`<tr data-report-id="${escapeHtml(report.id)}"><td class="report-title-cell"><div class="report-main"><img class="report-thumb" src="${escapeHtml(report.image||photoSet[report.category]||photoSet.Other)}" alt="" loading="lazy"><div><div class="report-name">${escapeHtml(report.title)}</div><div class="report-meta"><span class="report-id">${escapeHtml(report.id)}</span><span class="category-mini">${escapeCategory(report.category)}</span></div></div></div></td><td class="location-cell"><div class="location-name">${escapeHtml(report.location)}</div><div class="location-area">${escapeHtml(report.area)}</div></td><td><span class="priority-pill ${priorityClass(report.priority)}">${report.priority}</span>${report.duplicateOf?`<span class="duplicate-tag">↳ Similar to ${escapeHtml(report.duplicateOf)}</span>`:''}</td><td><span class="status-pill ${statusClass(report.status)}">${escapeHtml(report.status)}</span></td><td class="reported-time">${formatAge(report.reportedAt)}</td><td><button class="row-menu" aria-label="Open ${escapeHtml(report.id)}">›</button></td></tr>`).join('');document.getElementById('empty-state').hidden=visible.length>0;document.getElementById('queue-footer-text').textContent=visible.length?`Showing ${shown.length} of ${visible.length} reports`:'No reports found';document.getElementById('load-more-reports').hidden=shown.length>=visible.length}
function renderNeighborhoods(){const departmentsView=activeView==='departments',groups=[...new Set(reports.map(report=>departmentsView?(report.department||departments[report.category]||'Unassigned'):report.area))];document.querySelector('.pulse-section .section-kicker').textContent=departmentsView?'TEAM WORKLOAD':'PAKISTAN-WIDE PULSE';document.querySelector('.pulse-section h2').textContent=departmentsView?'Open reports by department':'Local reports across the country';document.getElementById('neighborhood-list').innerHTML=groups.map(group=>{const count=reports.filter(report=>(departmentsView?(report.department||departments[report.category]||'Unassigned')===group:report.area===group)&&report.status!=='Resolved').length;return `<div class="neighborhood-item"><button data-area-filter="${escapeHtml(group)}">${escapeHtml(group)}</button><span>${count}</span></div>`}).join('')}
function renderActivity(){const events=reports.flatMap(report=>(report.history||[]).map(event=>({...event,report}))).sort((a,b)=>b.time-a.time).slice(0,3);document.getElementById('activity-list').innerHTML=events.map((event,index)=>`<div class="activity-item"><span class="activity-marker ${index===1?'orange':''}">${event.status==='Resolved'?'✓':event.status==='In progress'?'↗':'+'}</span><div class="activity-copy"><b>${escapeHtml(event.report.id)}</b> · ${escapeHtml(event.note||event.status)}<div class="activity-time">${formatAge(event.time)} · ${escapeHtml(event.report.area)}</div></div></div>`).join('')}
function updateNavigation(){document.querySelectorAll('.nav-item[data-view]').forEach(button=>button.classList.toggle('active',button.dataset.view===activeView));const isOverview=activeView==='overview',name=currentAdminUser?.displayName||currentAdminUser?.name||'Ali Khan';document.getElementById('page-crumb').textContent=activeView==='departments'?'Department queues':activeView==='reports'?'All reports':'Operations overview';document.getElementById('page-title').innerHTML=isOverview?`Assalamu alaikum, ${escapeHtml(name)} <span class="heading-sun">✳</span>`:activeView==='departments'?'Department queues':'All civic reports';document.getElementById('page-subtitle').textContent=activeView==='overview'?'Your Pakistan-wide service desk: review urgent reports and coordinate local teams.':activeView==='departments'?'Review workload and handoffs across municipal service teams.':'Search, filter, and manage reports from every province and territory.';document.getElementById('queue-title').dataset.view=activeView;document.getElementById('status-filter').value=statusFilter;document.getElementById('metric-open-note').textContent=isOverview?`${new Set(reports.map(report=>report.area)).size} local areas`:'Across Pakistan'}
function openModal(content,small=false){const root=document.getElementById('modal-root');root.innerHTML=`<div class="modal-backdrop"><section class="modal ${small?'modal-small':''}" role="dialog" aria-modal="true">${content}</section></div>`;enhancePakistanLocationForm(root);const detailControls=root.querySelector('.detail-controls');if(detailControls&&!currentAdminUser){detailControls.hidden=true;detailControls.previousElementSibling.hidden=true;root.querySelector('.priority-explanation').hidden=true;root.querySelector('#save-update').hidden=true}root.addEventListener('click',event=>{if(event.target.closest('#save-update')&&!currentAdminUser){event.preventDefault();event.stopImmediatePropagation();toast('Administrator sign-in is required to update reports.')}},true);root.addEventListener('submit',event=>{if(event.target.id==='rules-form'&&!currentAdminUser){event.preventDefault();event.stopImmediatePropagation();toast('Administrator sign-in is required to change priority rules.')}},true);root.querySelector('.modal-backdrop').addEventListener('click',event=>{if(event.target.classList.contains('modal-backdrop'))closeModal()});root.querySelector('.modal-close')?.addEventListener('click',closeModal);document.addEventListener('keydown',escapeModal,{once:true});root.querySelector('input,textarea,select,button')?.focus()}
function enhancePakistanLocationForm(root){const form=root.querySelector('#new-report-form');if(!form)return;const areaField=form.elements.area.closest('.form-field');areaField.innerHTML='<label for="report-neighborhood">Neighborhood, sector, or union council</label><input id="report-neighborhood" name="neighborhood" maxlength="28" required placeholder="e.g. Gulshan-e-Iqbal, Block 7"><input id="report-area" name="area" type="hidden">';areaField.insertAdjacentHTML('beforebegin','<div class="form-field"><label for="report-city">City</label><input id="report-city" name="city" list="pakistan-cities" maxlength="20" required value="Karachi" placeholder="Enter your city"><datalist id="pakistan-cities"><option value="Karachi"><option value="Lahore"><option value="Islamabad"><option value="Rawalpindi"><option value="Peshawar"><option value="Quetta"><option value="Multan"><option value="Faisalabad"><option value="Hyderabad"><option value="Sialkot"><option value="Gilgit"><option value="Muzaffarabad"></datalist></div><div class="form-field"><label for="report-province">Province or territory</label><select id="report-province" name="province" required><option>Sindh</option><option>Punjab</option><option>Khyber Pakhtunkhwa</option><option>Balochistan</option><option>Islamabad Capital Territory</option><option>Gilgit-Baltistan</option><option>Azad Jammu and Kashmir</option></select></div>');const neighborhood=form.elements.neighborhood,city=form.elements.city,province=form.elements.province,area=form.elements.area;const provinceByCity={karachi:'Sindh',hyderabad:'Sindh',lahore:'Punjab',rawalpindi:'Punjab',multan:'Punjab',faisalabad:'Punjab',sialkot:'Punjab',peshawar:'Khyber Pakhtunkhwa',quetta:'Balochistan',islamabad:'Islamabad Capital Territory',gilgit:'Gilgit-Baltistan',muzaffarabad:'Azad Jammu and Kashmir'};const syncArea=()=>{const knownProvince=provinceByCity[city.value.trim().toLowerCase()];if(knownProvince)province.value=knownProvince;area.value=[neighborhood.value.trim(),city.value.trim(),province.value].filter(Boolean).join(', ').slice(0,80)};[neighborhood,city,province].forEach(field=>{field.addEventListener('input',syncArea);field.addEventListener('change',syncArea)});form.addEventListener('submit',syncArea,true);syncArea();form.elements.title.placeholder='A short description, e.g. Streetlight out near Hasan Square';form.elements.description.placeholder='Share the landmark, nearby road, and how the issue affects people.';form.elements.location.placeholder='Street, house/plot, block, sector, or nearby landmark';root.querySelector('#location-help').textContent='Enter a nearby landmark or street. GPS can add your coordinates with permission; please include a human-readable location too.'}
function enhancePakistanLocationForm(root){const form=root.querySelector('#new-report-form');if(!form)return;const areaField=form.elements.area.closest('.form-field');areaField.innerHTML='<label for="report-neighborhood">Area, village, sector, or union council</label><input id="report-neighborhood" name="neighborhood" maxlength="60" required placeholder="e.g. UC 4, Mohallah Noor, or Block 7"><input id="report-area" name="area" type="hidden">';areaField.insertAdjacentHTML('beforebegin','<div class="form-field"><label for="report-province">Province or territory</label><select id="report-province" name="province" required><option value="">Choose a province or territory</option><option>Sindh</option><option>Punjab</option><option>Khyber Pakhtunkhwa</option><option>Balochistan</option><option>Islamabad Capital Territory</option><option>Gilgit-Baltistan</option><option>Azad Jammu and Kashmir</option></select></div><div class="form-field"><label for="report-city">City or town</label><input id="report-city" name="city" list="pakistan-cities" maxlength="60" required autocomplete="address-level2" placeholder="Enter any city, town, or village"><datalist id="pakistan-cities"><option value="Karachi"><option value="Hyderabad"><option value="Sukkur"><option value="Larkana"><option value="Mirpur Khas"><option value="Thatta"><option value="Badin"><option value="Khairpur"><option value="Lahore"><option value="Faisalabad"><option value="Rawalpindi"><option value="Multan"><option value="Bahawalpur"><option value="Sahiwal"><option value="Rahim Yar Khan"><option value="Dera Ghazi Khan"><option value="Peshawar"><option value="Mardan"><option value="Abbottabad"><option value="Mingora"><option value="Kohat"><option value="Bannu"><option value="Quetta"><option value="Gwadar"><option value="Turbat"><option value="Khuzdar"><option value="Sibi"><option value="Islamabad"><option value="Gilgit"><option value="Skardu"><option value="Chilas"><option value="Muzaffarabad"><option value="Mirpur"><option value="Kotli"><option value="Rawalakot"></datalist></div><div class="form-field"><label for="report-district">District or tehsil <span class="field-help">(optional)</span></label><input id="report-district" name="district" maxlength="60" placeholder="Add this to help route reports in smaller places"></div>');const neighborhood=form.elements.neighborhood,city=form.elements.city,province=form.elements.province,district=form.elements.district,area=form.elements.area;const provinceByCity={karachi:'Sindh',hyderabad:'Sindh',sukkur:'Sindh',larkana:'Sindh','mirpur khas':'Sindh',thatta:'Sindh',badin:'Sindh',khairpur:'Sindh',lahore:'Punjab',faisalabad:'Punjab',rawalpindi:'Punjab',multan:'Punjab',bahawalpur:'Punjab',sahiwal:'Punjab','rahim yar khan':'Punjab','dera ghazi khan':'Punjab',mardan:'Khyber Pakhtunkhwa',peshawar:'Khyber Pakhtunkhwa',abbottabad:'Khyber Pakhtunkhwa',mingora:'Khyber Pakhtunkhwa',kohat:'Khyber Pakhtunkhwa',bannu:'Khyber Pakhtunkhwa',quetta:'Balochistan',gwadar:'Balochistan',turbat:'Balochistan',khuzdar:'Balochistan',sibi:'Balochistan',islamabad:'Islamabad Capital Territory',gilgit:'Gilgit-Baltistan',skardu:'Gilgit-Baltistan',chilas:'Gilgit-Baltistan',muzaffarabad:'Azad Jammu and Kashmir',mirpur:'Azad Jammu and Kashmir',kotli:'Azad Jammu and Kashmir',rawalakot:'Azad Jammu and Kashmir'};const syncArea=()=>{const knownProvince=provinceByCity[city.value.trim().toLowerCase()];if(knownProvince)province.value=knownProvince;area.value=[neighborhood.value.trim(),district.value.trim(),city.value.trim(),province.value].filter(Boolean).join(', ').slice(0,160)};[neighborhood,city,province,district].forEach(field=>{field.addEventListener('input',syncArea);field.addEventListener('change',syncArea)});form.addEventListener('submit',syncArea,true);syncArea();form.elements.title.placeholder='A short description, e.g. Streetlight out near the main bazaar';form.elements.description.placeholder='Share a nearby landmark, road, or the union council and how this affects people.';form.elements.location.placeholder='Street, chowk, bazaar, village landmark, or nearby public place';root.querySelector('#location-help').textContent='Use the closest landmark people in your area know. GPS is optional; do not enter a private home address.'}
function closeModal(){document.getElementById('modal-root').innerHTML=''}
function escapeModal(event){if(event.key==='Escape')closeModal()}
function toast(message){const region=document.getElementById('toast-region');const item=document.createElement('div');item.className='toast';item.innerHTML=message;region.append(item);setTimeout(()=>item.remove(),3500)}
function updateAdminProfile(user){currentAdminUser=user||null;document.body.classList.toggle('is-admin',Boolean(currentAdminUser));document.querySelectorAll('.admin-only').forEach(element=>{element.hidden=!currentAdminUser});document.querySelector('.resident-nav').hidden=Boolean(currentAdminUser);const name=document.getElementById('profile-name'),role=document.getElementById('profile-role'),button=document.getElementById('admin-auth-button'),access=document.getElementById('admin-auth-side'),avatar=document.getElementById('profile-avatar');if(!name||!role||!button)return;const displayName=currentAdminUser?.displayName||currentAdminUser?.name||(currentAdminUser?.email==='admin@civicpulse.local'?'Ali Khan':currentAdminUser?.email?.split('@')[0])||'Ali Khan';name.textContent=displayName;role.textContent=currentAdminUser?'CivicPulse administrator · Pakistan':'Resident services · Pakistan';if(avatar)avatar.textContent=displayName.split(/\s+/).map(part=>part[0]).join('').slice(0,2).toUpperCase();button.title=currentAdminUser?'Administrator options':'Administrator sign in';button.setAttribute('aria-label',button.title);if(access){access.hidden=false;access.querySelector('.nav-label').textContent=currentAdminUser?'Administrator profile':'Administrator access';access.title=button.title;access.setAttribute('aria-label',button.title)}if(typeof activeView!=='undefined'&&document.getElementById('page-title'))updateNavigation()}
async function showAdminAuth(){if(!CivicPulseCloud.configured){toast('Add your Supabase project URL and publishable key to config.js to enable administrator sign-in.');return}try{const user=await CivicPulseCloud.currentUser();if(user){openModal(`<div class="modal-header"><div><div class="section-kicker">ADMINISTRATOR</div><h2>Signed in</h2><p>${escapeHtml(user.email||'Administrator')}</p></div><button class="modal-close" aria-label="Close">×</button></div><div class="modal-body"><p class="detail-description">Admin changes are protected by your Supabase account.</p><div class="form-actions"><button class="button button-primary" id="admin-sign-out">Sign out</button></div></div>`,true);document.getElementById('admin-sign-out').addEventListener('click',async()=>{try{await CivicPulseCloud.signOut();updateAdminProfile(null);closeModal();toast('Administrator signed out.')}catch(error){toast(escapeHtml(error.message))}});return}openModal(`<div class="modal-header"><div><div class="section-kicker">ADMINISTRATOR ACCESS</div><h2>Sign in</h2><p>Residents can submit and track reports without an account.</p></div><button class="modal-close" aria-label="Close">×</button></div><form class="modal-body" id="admin-login-form"><div class="form-field"><label for="admin-email">Email</label><input id="admin-email" type="email" autocomplete="username" required></div><div class="form-field" style="margin-top:12px"><label for="admin-password">Password</label><input id="admin-password" type="password" autocomplete="current-password" required></div><div class="form-actions"><button type="submit" class="button button-primary">Sign in</button></div></form>`,true);document.getElementById('admin-login-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;const button=form.querySelector('[type="submit"]');button.disabled=true;try{const user=await CivicPulseCloud.signIn(form.elements['admin-email'].value,form.elements['admin-password'].value);updateAdminProfile(user);closeModal();toast('Signed in as administrator.')}catch(error){toast(escapeHtml(error.message));button.disabled=false}})}catch(error){toast(escapeHtml(error.message))}}
async function initializeCloud(){if(!CivicPulseCloud.configured){if(CivicPulseCloud.configurationError)toast(escapeHtml(CivicPulseCloud.configurationError));updateAdminProfile(null);return}document.getElementById('sync-label').textContent='Connecting';try{const [loadedReports,loadedRules,user]=await Promise.all([CivicPulseCloud.listReports(),CivicPulseCloud.readRules(),CivicPulseCloud.currentUser()]);reports=loadedReports;syncedReports=new Map(reports.map(report=>[report.id,JSON.stringify(report)]));if(loadedRules)rules={...rules,...loadedRules};updateAdminProfile(user);render();document.getElementById('sync-label').textContent='Shared live data';CivicPulseCloud.subscribeToReports(async()=>{try{reports=await CivicPulseCloud.listReports();syncedReports=new Map(reports.map(report=>[report.id,JSON.stringify(report)]));render()}catch(error){toast('Could not refresh reports: '+escapeHtml(error.message))}})}catch(error){document.getElementById('sync-label').textContent='Connection error';toast('Cloud connection failed: '+escapeHtml(error.message))}}
function detectAndSuggest(title,description,location,area,chosen){const detected=categoryFor(`${title} ${description}`);const category=chosen==='auto'?detected.category:chosen;const candidate={id:'',title,description,location,area,category,lat:undefined,lng:undefined};const duplicate=findDuplicate(candidate);const score=priorityScore({...candidate,priority:'Medium',reportedAt:Date.now()},duplicate);return {category,confidence:chosen==='auto'?detected.confidence:100,duplicate,priority:priorityFromScore(score)}}
function showNewReport(){const form=`<div class="modal-header"><div><div class="section-kicker">RESIDENT INTAKE</div><h2>Report a civic issue</h2><p>Reports are shared with the relevant city service team.</p></div><button class="modal-close" aria-label="Close">×</button></div><form class="modal-body" id="new-report-form"><div class="form-grid"><div class="form-field full"><label for="report-title">What’s the issue?</label><input id="report-title" name="title" maxlength="90" required placeholder="A short description, e.g. Streetlight out on Cedar Ave"></div><div class="form-field full"><label for="report-description">Tell us a little more</label><textarea id="report-description" name="description" maxlength="800" required placeholder="What happened, and how is it affecting the neighborhood?"></textarea></div><div class="form-field"><label for="report-category">Category</label><select id="report-category" name="category"><option value="auto">Automatically detect</option><option>Streetlight</option><option>Road damage</option><option>Waste</option><option>Water & drainage</option><option>Other</option></select></div><div class="form-field"><label for="report-area">Neighborhood</label><select id="report-area" name="area"><option>Northside</option><option>Old Market</option><option>River Ward</option><option>Park East</option><option>West End</option></select></div><div class="form-field full"><label for="report-location">Approximate location</label><div class="inline-field"><input id="report-location" name="location" required maxlength="100" placeholder="Street, intersection, or nearby landmark"><button class="button button-quiet button-small" type="button" id="locate-button">Use my location</button></div><span class="field-help" id="location-help">A nearby intersection or landmark is enough. Precise address is not required.</span></div><div class="form-field full"><span class="form-label">Add a photo <span class="field-help">(optional)</span></span><label class="photo-drop" for="report-photo"><span class="photo-symbol">＋</span><span><b>Choose a photo</b><small>JPG or PNG, up to 5 MB</small></span><input id="report-photo" type="file" accept="image/jpeg,image/png,image/webp"></label><img id="photo-preview" class="photo-preview" alt="Selected report photo" hidden></div><div class="form-field full" id="classification-result"><div class="classification-box"><span>✳</span><span>Describe the issue and we’ll suggest a category, priority, and possible duplicates.</span></div></div></div><div class="form-actions"><button type="button" class="button button-quiet" id="cancel-report">Cancel</button><button type="submit" class="button button-primary">Submit report <span class="plus">→</span></button></div></form>`;openModal(form);const formEl=document.getElementById('new-report-form');let photoData='';let lat,lng;const refreshSuggestion=()=>{const title=formEl.elements.title.value.trim(),description=formEl.elements.description.value.trim(),location=formEl.elements.location.value.trim(),area=formEl.elements.area.value,chosen=formEl.elements.category.value;if(!title&&!description)return;const suggestion=detectAndSuggest(title||description,description,location||area,area,chosen);document.getElementById('classification-result').innerHTML=`<div class="classification-box"><span>✳</span><span>Suggested: <b>${escapeHtml(suggestion.category)}</b> · ${suggestion.confidence}% match · ${suggestion.priority} priority</span></div>${suggestion.duplicate?`<div class="duplicate-alert"><span>↳</span><span>Possible duplicate of <b>${escapeHtml(suggestion.duplicate.id)}</b> nearby. We’ll link these reports for the response team.</span></div>`:''}`};formEl.addEventListener('input',refreshSuggestion);formEl.elements.category.addEventListener('change',refreshSuggestion);document.getElementById('cancel-report').addEventListener('click',closeModal);document.getElementById('report-photo').addEventListener('change',event=>{const file=event.target.files[0];if(!file)return;if(file.size>5*1024*1024){toast('Photo must be under 5 MB.');event.target.value='';return}if(!file.type.startsWith('image/')){toast('Choose an image file.');event.target.value='';return}const reader=new FileReader();reader.onload=()=>{photoData=reader.result;const preview=document.getElementById('photo-preview');preview.src=photoData;preview.hidden=false};reader.readAsDataURL(file)});document.getElementById('locate-button').addEventListener('click',()=>{const button=document.getElementById('locate-button');if(!navigator.geolocation){toast('Location is unavailable in this browser.');return}button.disabled=true;button.textContent='Locating…';navigator.geolocation.getCurrentPosition(position=>{lat=position.coords.latitude;lng=position.coords.longitude;const label=`Near ${lat.toFixed(3)}, ${lng.toFixed(3)}`;formEl.elements.location.value=label;document.getElementById('location-help').textContent='Approximate device location added. You can edit this label.';button.disabled=false;button.textContent='Location added';refreshSuggestion()},()=>{button.disabled=false;button.textContent='Use my location';toast('Location permission was unavailable. You can enter a nearby landmark instead.')},{enableHighAccuracy:false,timeout:7000,maximumAge:60000})});formEl.addEventListener('submit',event=>{event.preventDefault();const title=formEl.elements.title.value.trim(),description=formEl.elements.description.value.trim(),location=formEl.elements.location.value.trim(),area=formEl.elements.area.value,chosen=formEl.elements.category.value;if(!title||!description||!location)return;const suggestion=detectAndSuggest(title,description,location,area,chosen);const id=`CP-${String(Math.max(...reports.map(report=>Number(report.id.slice(3))||0))+1).padStart(4,'0')}`;const now=Date.now();const report={id,title,description,category:suggestion.category,location,area,priority:suggestion.priority,score:priorityScore({priority:suggestion.priority,reportedAt:now,title,description},suggestion.duplicate),status:'Submitted',reportedAt:now,department:departments[suggestion.category]||'Public Works',reporter:'Resident',image:photoData||photoSet[suggestion.category]||photoSet.Other,lat,lng,duplicateOf:suggestion.duplicate?.id,history:[{status:'Submitted',time:now,note:suggestion.duplicate?`Possible duplicate of ${suggestion.duplicate.id}`:'Report received'}]};reports.unshift(report);saveReports();render();closeModal();toast(`Report <b>${escapeHtml(id)}</b> submitted. Save your reference number to track progress.`)})}
function showReportDetail(id){const report=reports.find(item=>item.id===id);if(!report)return;const history=report.history||[];const timeline=['Submitted','In progress','Resolved'];const timelineHtml=timeline.map((status,index)=>{const reached=timeline.indexOf(report.status)>=index;const current=report.status===status;return `<div class="timeline-step ${reached?'done':''} ${current?'current':''}">${status}</div>`}).join('');const duplicate=report.duplicateOf?`<div class="duplicate-alert"><span>↳</span><span>Linked as a possible duplicate of <b>${escapeHtml(report.duplicateOf)}</b>. Reports stay visible separately.</span></div>`:'';const resolution=report.status==='Resolved'?`<div class="detail-section-title">Resolution evidence</div><p class="detail-description">${escapeHtml(report.resolution||'Issue resolved by the assigned team.')}</p>${report.resolutionImage?`<img class="detail-photo" src="${escapeHtml(report.resolutionImage)}" alt="Resolution evidence">`:''}`:'';const content=`<div class="modal-header"><div><div class="section-kicker">${escapeHtml(report.category.toUpperCase())} · ${escapeHtml(report.area.toUpperCase())}</div><h2>${escapeHtml(report.id)} · Report details</h2><p>Submitted ${formatAge(report.reportedAt)} by ${escapeHtml(report.reporter||'Resident')}</p></div><button class="modal-close" aria-label="Close">×</button></div><div class="modal-body"><div class="detail-topline"><div><h3 class="detail-title">${escapeHtml(report.title)}</h3><div class="detail-id">${escapeHtml(report.location)}</div></div><span class="priority-pill ${priorityClass(report.priority)}">${report.priority} priority</span></div><img class="detail-photo" src="${escapeHtml(report.image||photoSet[report.category]||photoSet.Other)}" alt="Photo for ${escapeHtml(report.title)}"><p class="detail-description">${escapeHtml(report.description)}</p><div class="detail-facts"><div class="detail-fact"><small>Assigned department</small><b>${escapeHtml(report.department||departments[report.category])}</b></div><div class="detail-fact"><small>Current status</small><b><span class="status-line"><i class="live-dot"></i>${escapeHtml(report.status)}</span></b></div></div>${duplicate}<div class="detail-section-title">Progress</div><div class="timeline">${timelineHtml}</div>${history.length?`<div class="activity-list">${history.slice().reverse().map(event=>`<div class="activity-item"><span class="activity-marker">${event.status==='Resolved'?'✓':event.status==='In progress'?'↗':'+'}</span><div class="activity-copy"><b>${escapeHtml(event.status)}</b> · ${escapeHtml(event.note)}<div class="activity-time">${new Date(event.time).toLocaleString()}</div></div></div>`).join('')}</div>`:''}${resolution}<div class="detail-section-title">Update report</div><div class="detail-controls"><div class="form-field"><label for="detail-status">Status</label><select id="detail-status"><option ${report.status==='Submitted'?'selected':''}>Submitted</option><option ${report.status==='In progress'?'selected':''}>In progress</option><option ${report.status==='Resolved'?'selected':''}>Resolved</option></select></div><div class="form-field"><label for="detail-department">Department</label><select id="detail-department">${['Public Works','Roads & Transport','Sanitation','Water Services'].map(name=>`<option ${report.department===name?'selected':''}>${name}</option>`).join('')}</select></div><div class="form-field full"><label for="detail-note">Update note</label><textarea id="detail-note" placeholder="Describe the action taken or next step…" maxlength="400"></textarea></div><div class="form-field full"><label for="resolution-photo">Resolution photo <span class="field-help">(optional)</span></label><input id="resolution-photo" type="file" accept="image/jpeg,image/png,image/webp"></div></div><div class="priority-explanation">Priority score ${report.score||priorityScore(report,Boolean(report.duplicateOf))}/100 · Based on reported urgency, time open, and duplicate signals.</div><div class="form-actions"><button class="button button-quiet" id="track-this">Resident tracking view</button><button class="button button-primary" id="save-update">Save update</button></div></div>`;openModal(content);document.getElementById('track-this').addEventListener('click',()=>showTrackingResult(report.id));document.getElementById('save-update').addEventListener('click',()=>{const nextStatus=document.getElementById('detail-status').value,department=document.getElementById('detail-department').value,note=document.getElementById('detail-note').value.trim(),photoFile=document.getElementById('resolution-photo').files[0];const applyUpdate=resolutionImage=>{const now=Date.now();report.department=department;report.status=nextStatus;if(nextStatus==='Resolved'){report.resolvedAt=now;report.resolution=note||report.resolution||'Issue resolved by the assigned city team.';if(resolutionImage)report.resolutionImage=resolutionImage}if(nextStatus!=='Resolved')delete report.resolvedAt;if(note||nextStatus!==history.at(-1)?.status)report.history.push({status:nextStatus,time:now,note:note||`Status updated to ${nextStatus}`});saveReports();render();closeModal();toast(`<b>${escapeHtml(report.id)}</b> updated and shared with ${escapeHtml(department)}.`)};if(photoFile){if(photoFile.size>5*1024*1024){toast('Resolution photo must be under 5 MB.');return}const reader=new FileReader();reader.onload=()=>applyUpdate(reader.result);reader.readAsDataURL(photoFile)}else applyUpdate(null)})}
function showTracking(){openModal(`<div class="modal-header"><div><div class="section-kicker">RESIDENT SERVICES</div><h2>Track a report</h2><p>Enter the reference number from your confirmation.</p></div><button class="modal-close" aria-label="Close">×</button></div><form class="modal-body" id="tracking-form"><div class="form-field"><label for="tracking-id">Report reference</label><input id="tracking-id" class="modal-input" required placeholder="For example, CP-2481" autocomplete="off"></div><div class="form-actions"><button type="button" class="button button-quiet" id="tracking-cancel">Close</button><button class="button button-primary" type="submit">Find report →</button></div><div id="tracking-result"></div></form>`,true);document.getElementById('tracking-cancel').addEventListener('click',closeModal);document.getElementById('tracking-form').addEventListener('submit',event=>{event.preventDefault();showTrackingResult(document.getElementById('tracking-id').value.trim().toUpperCase())})}
function showTrackingResult(id){const report=reports.find(item=>item.id.toUpperCase()===id.toUpperCase());const content=report?`<div class="tracking-result"><h3>${escapeHtml(report.title)}</h3><p>${escapeHtml(report.id)} · ${escapeHtml(report.location)} · ${escapeHtml(report.area)}</p><div class="status-line"><i class="live-dot"></i><b>${escapeHtml(report.status)}</b> · ${escapeHtml(report.department||departments[report.category])}</div><div class="timeline">${['Submitted','In progress','Resolved'].map((status,index)=>`<div class="timeline-step ${timelineReached(report.status,index)?'done':''} ${status===report.status?'current':''}">${status}</div>`).join('')}</div>${report.status==='Resolved'?`<p style="margin:10px 0 0">${escapeHtml(report.resolution||'Issue resolved by the city team.')}</p>`:''}</div>`:`<div class="duplicate-alert"><span>?</span><span>We couldn’t find <b>${escapeHtml(id)}</b>. Check the reference and try again.</span></div>`;const target=document.getElementById('tracking-result');if(target){target.innerHTML=content;return}openModal(`<div class="modal-header"><div><div class="section-kicker">RESIDENT TRACKING</div><h2>${escapeHtml(report?.id||id)}</h2><p>Current report progress</p></div><button class="modal-close" aria-label="Close">×</button></div><div class="modal-body">${content}<div class="form-actions"><button class="button button-quiet" id="tracking-back">Back to dashboard</button></div></div>`,true);document.getElementById('tracking-back').addEventListener('click',closeModal)}
function timelineReached(status,index){return ['Submitted','In progress','Resolved'].indexOf(status)>=index}
document.getElementById('admin-auth-button').addEventListener('click',showAdminAuth);
document.getElementById('admin-auth-side').addEventListener('click',showAdminAuth);
initializeCloud();
function showRules(){const content=`<div class="modal-header"><div><div class="section-kicker">CONFIGURATION</div><h2>Priority rules</h2><p>Adjust how reports are scored for triage. Scores are capped at 100.</p></div><button class="modal-close" aria-label="Close">×</button></div><form class="modal-body" id="rules-form">${[['baseHigh','High priority starting score','Score for high-impact issues'],['baseMedium','Medium priority starting score','Score for standard issues'],['ageBoost','Age boost per hour','Added while a report remains open'],['duplicateBoost','Duplicate signal boost','Added when a nearby report is similar'],['urgentBoost','Safety language boost','Added for urgency or safety keywords']].map(([key,label,help])=>`<label class="rule-row"><span><b>${label}</b><small>${help}</small></span><input type="number" min="0" max="100" step="${key==='ageBoost'?'0.1':'1'}" name="${key}" value="${rules[key]}"></label>`).join('')}<div class="form-actions"><button type="button" class="button button-quiet" id="rules-cancel">Cancel</button><button type="submit" class="button button-primary">Save rules</button></div></form>`;openModal(content,true);document.getElementById('rules-cancel').addEventListener('click',closeModal);document.getElementById('rules-form').addEventListener('submit',event=>{event.preventDefault();const data=new FormData(event.currentTarget);rules=Object.fromEntries([...data].map(([key,value])=>[key,Number(value)]));saveRules();reports=reports.map(report=>({...report,score:priorityScore(report,Boolean(report.duplicateOf)),priority:priorityFromScore(priorityScore(report,Boolean(report.duplicateOf)))}));saveReports();render();closeModal();toast('Priority rules saved. Queue scores have been recalculated.')})}
function setView(view){if(['reports','departments'].includes(view)&&!currentAdminUser){showAdminAuth();return}activeView=view;activePriority='all';statusFilter='all';searchQuery='';document.getElementById('search-input').value='';render()}

async function showAdminAuth(){if(!CivicPulseCloud.configured){toast('Administrator access is unavailable until the local API or Supabase is configured.');return}try{const user=await CivicPulseCloud.currentUser();if(user){const authDescription=window.CIVICPULSE_CONFIG?.supabaseUrl?'Administrator access is connected to the shared service.':'You are signed in to the local Pakistan operations console.';openModal(`<div class="modal-header"><div><div class="section-kicker">ADMINISTRATOR PROFILE</div><h2>${escapeHtml(user.displayName||user.name||'Administrator')}</h2><p>${escapeHtml(user.email||'Administrator')}</p></div><button class="modal-close" aria-label="Close">×</button></div><div class="modal-body"><p class="detail-description">${authDescription}</p><div class="form-actions"><button class="button button-primary" id="admin-sign-out">Sign out</button></div></div>`,true);document.getElementById('admin-sign-out').addEventListener('click',async()=>{const button=document.getElementById('admin-sign-out');button.disabled=true;try{await CivicPulseCloud.signOut();updateAdminProfile(null);setView('overview');closeModal();toast('Administrator signed out.')}catch(error){toast(escapeHtml(error.message));button.disabled=false}});return}openModal(`<div class="modal-header"><div><div class="section-kicker">SECURE OPERATIONS ACCESS</div><h2>Administrator sign in</h2><p>Residents can submit and track reports without an account.</p></div><button class="modal-close" aria-label="Close">×</button></div><form class="modal-body" id="admin-login-form"><div class="form-field"><label for="admin-email">Email</label><input id="admin-email" type="email" autocomplete="username" required></div><div class="form-field" style="margin-top:12px"><label for="admin-password">Password</label><input id="admin-password" type="password" autocomplete="current-password" required></div><div class="form-actions"><button type="submit" class="button button-primary">Sign in to operations</button></div></form>`,true);document.getElementById('admin-login-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('[type="submit"]');button.disabled=true;try{const signedInUser=await CivicPulseCloud.signIn(form.elements['admin-email'].value,form.elements['admin-password'].value);updateAdminProfile(signedInUser);setView('overview');closeModal();toast('Signed in to administrator operations.')}catch(error){toast(escapeHtml(error.message));button.disabled=false}})}catch(error){toast(escapeHtml(error.message))}}

async function initializeCloud(){if(!CivicPulseCloud.configured){if(CivicPulseCloud.configurationError)toast(escapeHtml(CivicPulseCloud.configurationError));updateAdminProfile(null);return}const syncLabel=document.getElementById('sync-label');syncLabel.textContent='Connecting';try{const [loadedReports,loadedRules,user]=await Promise.all([CivicPulseCloud.listReports(),CivicPulseCloud.readRules(),CivicPulseCloud.currentUser()]);reports=loadedReports;syncedReports=new Map(reports.map(report=>[report.id,JSON.stringify(report)]));if(loadedRules)rules={...rules,...loadedRules};updateAdminProfile(user);render();syncLabel.textContent=window.CIVICPULSE_CONFIG?.supabaseUrl?'Shared live data':'Local API · SQLite';CivicPulseCloud.subscribeToReports(async()=>{try{reports=await CivicPulseCloud.listReports();syncedReports=new Map(reports.map(report=>[report.id,JSON.stringify(report)]));render()}catch(error){toast('Could not refresh reports: '+escapeHtml(error.message))}})}catch(error){syncLabel.textContent='Connection error';toast('Service connection failed: '+escapeHtml(error.message))}}

document.getElementById('today-label').textContent=formatDate(new Date());document.getElementById('date-pill').textContent=formatDate(new Date());document.querySelectorAll('.nav-item[data-view]').forEach(button=>button.addEventListener('click',()=>setView(button.dataset.view)));document.getElementById('new-report-button').addEventListener('click',showNewReport);document.getElementById('track-button').addEventListener('click',showTracking);document.getElementById('track-nav').addEventListener('click',showTracking);document.getElementById('rules-nav').addEventListener('click',showRules);document.querySelectorAll('.filter-tab').forEach(button=>button.addEventListener('click',()=>{activePriority=button.dataset.priority;document.querySelectorAll('.filter-tab').forEach(tab=>tab.classList.toggle('active',tab===button));renderRows()}));document.getElementById('status-filter').addEventListener('change',event=>{statusFilter=event.target.value;renderRows()});document.getElementById('search-input').addEventListener('input',event=>{searchQuery=event.target.value.toLowerCase().trim();renderRows()});document.getElementById('report-rows').addEventListener('click',event=>{const row=event.target.closest('tr[data-report-id]');if(row)showReportDetail(row.dataset.reportId)});document.getElementById('clear-filters').addEventListener('click',()=>{activePriority='all';statusFilter='all';searchQuery='';document.getElementById('search-input').value='';document.querySelectorAll('.filter-tab').forEach((tab,index)=>tab.classList.toggle('active',index===0));renderRows()});document.getElementById('neighborhood-list').addEventListener('click',event=>{const button=event.target.closest('[data-area-filter]');if(button){searchQuery=button.dataset.areaFilter.toLowerCase();document.getElementById('search-input').value=button.dataset.areaFilter;renderRows()}});document.querySelectorAll('.map-pin').forEach(button=>button.addEventListener('click',()=>{searchQuery=button.dataset.mapArea.toLowerCase();document.getElementById('search-input').value=button.dataset.mapArea;renderRows()}));document.getElementById('activity-view-all').addEventListener('click',()=>setView('reports'));render();
